#include "platform/openvr/overlay_manager.hpp"
#include <array>
namespace bailout::platform::openvr { namespace {
constexpr char kDashboardKey[]="com.steamvr-bail-out.dashboard";constexpr char kWristKey[]="com.steamvr-bail-out.wrist";constexpr char kHudKey[]="com.steamvr-bail-out.hud";
vr::HmdMatrix34_t wrist_transform(){vr::HmdMatrix34_t m={{{1,0,0,0.0f},{0,1,0,-0.055f},{0,0,1,-0.115f}}};return m;}
vr::HmdMatrix34_t hud_transform(){vr::HmdMatrix34_t m={{{1,0,0,0.30f},{0,1,0,0.17f},{0,0,1,-0.70f}}};return m;}
}
bool OverlayManager::initialize(){if(!overlays_){error_="IVROverlay unavailable";return false;}if(!renderer_.initialize()){error_=renderer_.error();return false;}if(!renderer_.create_surface("dashboard",1024,640)||!renderer_.create_surface("thumbnail",256,256)||!renderer_.create_surface("wrist",768,384)||!renderer_.create_surface("hud",768,256)){error_="overlay texture creation failed";return false;}
 if(overlays_->CreateDashboardOverlay(kDashboardKey,"SteamVR Bail Out",&dashboard_,&thumbnail_)!=vr::VROverlayError_None||overlays_->CreateOverlay(kWristKey,"Bail Out Wrist",&wrist_)!=vr::VROverlayError_None||overlays_->CreateOverlay(kHudKey,"Bail Out HUD",&hud_)!=vr::VROverlayError_None){error_="OpenVR overlay creation failed";shutdown();return false;}
 overlays_->SetOverlayWidthInMeters(dashboard_,1.5f);overlays_->SetOverlayInputMethod(dashboard_,vr::VROverlayInputMethod_Mouse);vr::HmdVector2_t dashboard_scale{{1024,640}};overlays_->SetOverlayMouseScale(dashboard_,&dashboard_scale);
 overlays_->SetOverlayWidthInMeters(wrist_,0.27f);overlays_->SetOverlayInputMethod(wrist_,vr::VROverlayInputMethod_None);
 overlays_->SetOverlayWidthInMeters(hud_,0.42f);overlays_->SetOverlayInputMethod(hud_,vr::VROverlayInputMethod_None);auto hm=hud_transform();overlays_->SetOverlayTransformTrackedDeviceRelative(hud_,vr::k_unTrackedDeviceIndex_Hmd,&hm);
 SurfaceModel thumb{L"Bail Out",L"Safe VR game exit",L"",L"",L"",0,false,false};submit(thumbnail_,"thumbnail",thumb);return true;}
void OverlayManager::shutdown(){if(!overlays_)return;for(auto h:{wrist_,hud_,dashboard_})if(h!=vr::k_ulOverlayHandleInvalid)overlays_->DestroyOverlay(h);wrist_=hud_=dashboard_=thumbnail_=vr::k_ulOverlayHandleInvalid;wrist_visible_=false;}
bool OverlayManager::submit(vr::VROverlayHandle_t h,const std::string&id,const SurfaceModel&m){if(h==vr::k_ulOverlayHandleInvalid||!renderer_.render(id,m))return false;vr::Texture_t t{renderer_.texture(id),vr::TextureType_DirectX,vr::ColorSpace_Auto};return overlays_->SetOverlayTexture(h,&t)==vr::VROverlayError_None;}
void OverlayManager::show_wrist(uint32_t d,const SurfaceModel&m){if(d==vr::k_unTrackedDeviceIndexInvalid)return;bool same_content=wrist_model_.title==m.title&&wrist_model_.body==m.body&&wrist_model_.left_button==m.left_button&&wrist_model_.right_button==m.right_button&&wrist_model_.progress==m.progress;SurfaceModel next=m;if(same_content){next.left_hover=wrist_model_.left_hover;next.right_hover=wrist_model_.right_hover;}wrist_model_=std::move(next);if(!same_content)submit(wrist_,"wrist",wrist_model_);auto transform=wrist_transform();overlays_->SetOverlayTransformTrackedDeviceRelative(wrist_,d,&transform);overlays_->ShowOverlay(wrist_);wrist_visible_=true;}
void OverlayManager::hide_wrist(){if(wrist_!=vr::k_ulOverlayHandleInvalid)overlays_->HideOverlay(wrist_);wrist_visible_=false;}
void OverlayManager::show_hud(const SurfaceModel&m){submit(hud_,"hud",m);overlays_->ShowOverlay(hud_);}void OverlayManager::hide_hud(){if(hud_!=vr::k_ulOverlayHandleInvalid)overlays_->HideOverlay(hud_);}void OverlayManager::update_dashboard(const SurfaceModel&m){submit(dashboard_,"dashboard",m);}
std::vector<OverlayAction> OverlayManager::poll_wrist_events(const app::HandPose& hand,bool confirming,bool counting){std::vector<OverlayAction> out;bool left=false,right=false;if(wrist_visible_&&hand.tracked){vr::VROverlayIntersectionParams_t params{};params.eOrigin=vr::TrackingUniverseStanding;params.vSource={{hand.position.x,hand.position.y,hand.position.z}};params.vDirection={{hand.forward.x,hand.forward.y,hand.forward.z}};vr::VROverlayIntersectionResults_t hit{};if(overlays_->ComputeOverlayIntersection(wrist_,&params,&hit)){float x=hit.vUVs.v[0]*768.0f,y=(1.0f-hit.vUVs.v[1])*384.0f;left=y>=272&&y<=330&&x>=42&&x<=372;right=y>=272&&y<=330&&x>=396&&x<=726;}}if(wrist_model_.left_hover!=left||wrist_model_.right_hover!=right){wrist_model_.left_hover=left;wrist_model_.right_hover=right;submit(wrist_,"wrist",wrist_model_);}bool pressed=(hand.buttons&vr::ButtonMaskFromId(vr::k_EButton_SteamVR_Trigger))!=0;bool clicked=pressed&&!trigger_was_pressed_;trigger_was_pressed_=pressed;if(!clicked)return out;if(counting){if(right)out.push_back(OverlayAction::Cancel);}else if(confirming){if(left)out.push_back(OverlayAction::Confirm);else if(right)out.push_back(OverlayAction::Dismiss);}else{if(left)out.push_back(OverlayAction::Primary);else if(right)out.push_back(OverlayAction::Dismiss);}return out;}
std::vector<DashboardEvent> OverlayManager::poll_dashboard_events(){std::vector<DashboardEvent>out;vr::VREvent_t e{};while(overlays_->PollNextOverlayEvent(dashboard_,&e,sizeof(e))){if(e.eventType==vr::VREvent_MouseMove||e.eventType==vr::VREvent_MouseButtonDown)out.push_back({e.data.mouse.x,e.data.mouse.y,e.eventType==vr::VREvent_MouseButtonDown});}return out;}
}
